package com.morongaming.forsakenrealm;
import android.graphics.*;import org.json.JSONObject;
/** Textured raised furniture in the existing 2:1 projection; collision footprints stay server-owned. */
final class FurniturePainter {
 final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String key,Bitmap value){return value.getByteCount();}};final Bitmap texture;final Paint p=new Paint(3);final Matrix mapping=new Matrix();final Path path=new Path();final float[] source=new float[8],dest=new float[8];
 InteriorFurnishings furnishings;
 FurniturePainter(Bitmap texture){this.texture=texture;}
 FurniturePainter(Bitmap texture,android.content.Context context){this(texture);furnishings=new InteriorFurnishings(context);}
 float sx(float x,float y){return x-y;}float sy(float x,float y,float z){return (x+y)*.5f-z;}
 void face(Canvas c,int material,int shade,float... v){path.reset();for(int i=0;i<4;i++){dest[i*2]=sx(v[i*3],v[i*3+1]);dest[i*2+1]=sy(v[i*3],v[i*3+1],v[i*3+2]);if(i==0)path.moveTo(dest[0],dest[1]);else path.lineTo(dest[i*2],dest[i*2+1]);}path.close();if(texture!=null){int cw=texture.getWidth()/2,ch=texture.getHeight()/2;float l=material%2*cw+2,t=material/2*ch+2,r=l+cw-4,b=t+ch-4;source[0]=l;source[1]=t;source[2]=r;source[3]=t;source[4]=r;source[5]=b;source[6]=l;source[7]=b;mapping.setPolyToPoly(source,0,dest,0,dest[0]==dest[6]&&dest[1]==dest[7]?3:4);c.save();c.clipPath(path);p.setColor(Color.WHITE);c.drawBitmap(texture,mapping,p);c.restore();}else{p.setColor(material==0?0xff694d34:0xff73736a);c.drawPath(path,p);}if(shade>0){p.setColor(shade<<24);c.drawPath(path,p);}p.setColor(0x5030251a);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(.8f);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}
 void box(Canvas c,float x,float y,float z,float w,float d,float h,int material){face(c,material,90,x+w,y,z+h,x+w,y+d,z+h,x+w,y+d,z,x+w,y,z);face(c,material,45,x+w,y+d,z+h,x,y+d,z+h,x,y+d,z,x+w,y+d,z);face(c,material,0,x,y,z+h,x+w,y,z+h,x+w,y+d,z+h,x,y+d,z+h);}
 void line(Canvas c,int color,float width,float x,float y,float z,float a,float b,float h){p.setColor(color);p.setStrokeWidth(width);c.drawLine(sx(x,y),sy(x,y,z),sx(a,b),sy(a,b,h),p);}
 void draw(Canvas c,JSONObject f,long time){if(furnishings!=null&&furnishings.draw(c,f)){String label=f.optString("name");if(label.isEmpty())label=f.optString("kind").equals("anvil")?"SMITHING":f.optString("kind").equals("forge")?"FORGE":"";if(!label.isEmpty()){p.setTextSize(11);p.setColor(0xffe3d1a6);c.drawText(label,((float)f.optDouble("w")-(float)f.optDouble("h"))*.5f-p.measureText(label)*.5f,-65,p);}return;}float w=(float)f.optDouble("w"),d=(float)f.optDouble("h");String kind=f.optString("kind"),key=kind+":"+f.optString("name")+":"+w+":"+d;Bitmap bitmap=cache.get(key);if(bitmap==null){bitmap=Bitmap.createBitmap((int)(w+d+40),(int)((w+d)*.5f+190),Bitmap.Config.ARGB_8888);Canvas rendered=new Canvas(bitmap);rendered.translate(d+20,160);drawGeometry(rendered,f,-1);cache.put(key,bitmap);}p.setColor(Color.WHITE);c.drawBitmap(bitmap,-d-20,-160,p);String label=kind.equals("anvil")||kind.equals("forge")?"SMITHING":kind.equals("hearth")?"COOKING":kind.equals("loom")?"WEAVING":kind.equals("tannery")?"LEATHERWORK":kind.equals("mill")?"MILL":kind.equals("kiln")?"KILN":kind.equals("smoker")?"SMOKER":"";if(label.isEmpty())label=f.optString("name");if(!label.isEmpty()){p.setTextSize(11);p.setColor(0xffe3d1a6);c.drawText(label,(w-d)*.5f-p.measureText(label)*.5f,-55,p);}if(kind.equals("forge")||kind.equals("hearth")||kind.equals("kiln"))fire(c,w*.5f,d*.63f,30,time);}
 void drawGeometry(Canvas c,JSONObject f,long time){float w=(float)f.optDouble("w"),d=(float)f.optDouble("h");String k=f.optString("kind");path.reset();path.moveTo(8,6);path.lineTo(w+12,w*.5f+8);path.lineTo(w-d+12,(w+d)*.5f+10);path.lineTo(-d+5,d*.5f+6);path.close();p.setColor(0x65000000);c.drawPath(path,p);
 if(k.equals("table")&&f.optString("name").equals("Planting bed")){box(c,0,0,0,w,d,18,0);box(c,5,5,18,w-10,d-10,2,0);for(int row=0;row<4;row++)line(c,0xff33291b,4,9,10+row*(d-20)/4,21,w-9,10+row*(d-20)/4,21);}
 else if(k.equals("rack")&&(f.optString("name").contains("stall")||f.optString("name").contains("pen"))){for(float x:new float[]{0,w-8})for(float y:new float[]{0,d-8})box(c,x,y,0,8,8,55,0);for(float z:new float[]{20,42}){box(c,0,0,z,w,6,6,0);box(c,0,0,z,6,d,6,0);box(c,w-6,0,z,6,d,6,0);}box(c,15,15,0,w-30,25,16,0);for(int n=0;n<6;n++)line(c,0xffb5a65a,3,19+n*(w-40)/6,19,18,27+n*(w-40)/6,32,18);}
 else if(k.equals("rack")&&f.optString("name").equals("Herb drying")){box(c,0,d/2,0,8,8,75,0);box(c,w-8,d/2,0,8,8,75,0);box(c,0,d/2,70,w,8,7,0);for(int n=0;n<5;n++){float x=12+n*(w-24)/5;line(c,0xffa69660,2,x,d/2,70,x,d/2,38);box(c,x-4,d/2-3,34,9,8,17,0);line(c,0xff698045,5,x,d/2+5,52,x+3,d/2+5,30);}}
 else if(k.equals("rack")&&f.optString("name").isEmpty()){for(float x:new float[]{0,w-8})box(c,x,0,0,8,d,82,0);for(float z:new float[]{10,40,72}){box(c,0,0,z,w,d,6,0);for(int n=0;n<3;n++)box(c,12+n*(w-20)/3,5,z+6,18,d-14,19,0);}}
 else if(k.equals("table")){for(float x:new float[]{6,w-14})for(float y:new float[]{6,d-14})box(c,x,y,0,8,8,42,0);box(c,9,d/2,12,w-18,6,6,0);box(c,0,0,42,w,d,8,0);}
 else if(k.equals("bed")){box(c,0,0,0,w,d,18,0);box(c,5,7,18,w-10,d-14,16,3);box(c,0,0,18,w,7,40,0);box(c,0,d-6,18,w,6,15,0);box(c,12,14,34,w-24,28,7,3);box(c,7,52,34,w-14,d-64,3,3);line(c,0xff787258,2,7,52,38,w-7,52,38);}
 else if(k.equals("crate")||k.equals("box")||k.equals("chest")){box(c,0,0,0,w,d,43,0);box(c,1,1,43,w-2,d-2,5,0);for(float bx:new float[]{5,w-10}){face(c,2,0,bx,0,48.4f,bx+5,0,48.4f,bx+5,d,48.4f,bx,d,48.4f);face(c,2,35,bx,d+.3f,48,bx+5,d+.3f,48,bx+5,d+.3f,0,bx,d+.3f,0);}box(c,w*.43f,d,23,w*.14f,3,13,2);}
 else if(k.equals("counter")){box(c,0,0,0,w,d,58,0);box(c,-3,-3,58,w+6,d+6,6,0);for(int i=1;i<5;i++){line(c,0xff2a2119,2,w*i/5,d+.5f,4,w*i/5,d+.5f,54);box(c,w*i/5-12,d,34,12,3,3,2);}}
 else if(k.equals("anvil")){box(c,w*.25f,d*.2f,0,w*.5f,d*.6f,33,0);box(c,w*.14f,d*.12f,33,w*.72f,d*.76f,8,2);box(c,w*.3f,d*.25f,41,w*.4f,d*.5f,15,2);box(c,w*.3f,d*.12f,56,w*.7f,d*.76f,10,2);face(c,2,0,0,d*.5f,62,w*.3f,d*.12f,66,w*.3f,d*.88f,66,0,d*.5f,62);face(c,2,55,0,d*.5f,62,w*.3f,d*.88f,66,w*.3f,d*.88f,56,0,d*.5f,62);}
 else if(k.equals("forge")||k.equals("hearth")||k.equals("kiln")){box(c,0,0,0,w,d,24,1);box(c,0,0,24,w,13,k.equals("kiln")?86:65,1);box(c,0,12,24,12,d-12,35,1);box(c,w-12,12,24,12,d-12,35,1);box(c,14,15,24,w-28,d-24,5,2);fire(c,w*.5f,d*.63f,30,time);if(k.equals("kiln"))box(c,0,0,100,w,d*.65f,12,1);}
 else if(k.equals("loom")||k.equals("tannery")){box(c,0,0,0,10,d,8,0);box(c,w-10,0,0,10,d,8,0);box(c,0,d*.45f,8,9,9,84,0);box(c,w-9,d*.45f,8,9,9,84,0);box(c,0,d*.45f,88,w,10,8,0);face(c,3,k.equals("tannery")?55:0,12,d*.45f,82,w-12,d*.45f,82,w-12,d*.45f,24,12,d*.45f,24);box(c,6,d*.45f,20,w-12,8,7,0);}
 else if(k.equals("rack")){for(float x:new float[]{0,w-8}){box(c,x,0,0,8,d,8,0);box(c,x,d*.5f,5,8,8,76,0);}box(c,0,d*.5f,70,w,9,8,0);for(int i=1;i<=4;i++){float x=w*i/5;line(c,0xff987245,4,x,d*.5f+10,3,x,d*.5f+10,88);line(c,0xffa7aeab,5,x,d*.5f+10,88,x,d*.5f+10,103);}}
 else if(k.equals("mill")){box(c,8,8,0,w-16,d-16,36,0);box(c,0,0,36,w,d,15,1);box(c,3,3,51,w-6,d-6,7,1);box(c,w*.45f,d*.45f,58,8,8,22,0);box(c,w*.45f,d*.45f,76,w*.45f,8,6,0);}
 else if(k.equals("smoker")){box(c,0,0,0,w,d,96,0);for(float z:new float[]{30,77}){face(c,2,30,0,d+.2f,z+5,w,d+.2f,z+5,w,d+.2f,z,0,d+.2f,z);face(c,2,70,w+.2f,0,z+5,w+.2f,d,z+5,w+.2f,d,z,w+.2f,0,z);}box(c,-2,-2,96,w+4,d+4,7,2);box(c,w*.3f,d*.3f,103,w*.25f,d*.25f,24,2);box(c,w*.65f,d,48,7,4,18,2);}
 else box(c,0,0,0,w,d,45,0);
 }
 void fire(Canvas c,float x,float y,float z,long time){if(time<0)return;float px=sx(x,y),py=sy(x,y,z),flicker=(float)Math.sin(time/130.0)*4;p.setColor(0x12ff9b35);c.drawOval(px-52,py-27,px+52,py+24,p);p.setColor(0x22ff9b35);c.drawOval(px-40,py-21,px+40,py+17,p);p.setColor(0x33ff9b35);c.drawOval(px-30,py-16,px+30,py+12,p);for(int i=-1;i<=1;i++){path.reset();path.moveTo(px+i*11-7,py);path.lineTo(px+i*11+flicker,py-22-Math.abs(i)*4);path.lineTo(px+i*11+9,py);path.close();p.setColor(i==0?0xffffcf65:0xffd77b37);c.drawPath(path,p);}}
}



